#include<bits/stdc++.h>
using namespace std;
long long tong[1000005];
struct node
{
	int s,j;
}q[300005];
int main()
{
	int n;
	cin>>n;
	int head=1,tail=1;
	int k;
	int ans=0;
	int t;
	int x;
	for(int i=1;i<=n;i++)
	{
		cin>>t>>k;
		while(k--)
		{
			cin>>x;
			tong[x]++; 
			if(tong[x]==1) ans++; 
			q[tail]={t,x}; 
			tail++; 
		}
		while(head!=tail&&t-q[head].s>=86400) 
		{
			tong[q[head].j]--; 
			if(tong[q[head].j]==0) ans--;
			head++;  
		}
		cout<<ans<<endl; 
	}
	return 0;
}
